-- ===== schema =====

create table weapon_models (
  item_key text primary key,
  name_key text,
  name_ko text not null,
  name_en text not null,
  weapon_group text not null,
  family text,
  rarity_tier text,
  rpm numeric,
  base_mag_size integer,
  base_damage numeric,
  optimal_range numeric
);

alter table weapon_models enable row level security;
create policy "public read" on weapon_models for select using (true);


